    [TestFixture]
    public sealed class RelicCompatibilityTests
    {
        [Test] public void RelicApiKeepsThePreviouslySerializedEnumNumbersAndContractName()
        {
            Assert.AreEqual(1, (int)RunOfferKind.Relic);
            Assert.AreEqual(2, (int)UnlockKind.Relic);
            Assert.AreEqual(3, (int)UnlockKind.StartingDeck);
            Assert.AreEqual(8, (int)RunAction.UpgradeRelic);
            Assert.AreEqual(9, (int)RunAction.ReorderRelics);
            var contract = (DataContractAttribute)Attribute.GetCustomAttribute(typeof(RunRelic), typeof(DataContractAttribute));
            Assert.AreEqual("RunJoker", contract.Name);
        }
    }

